class Solution {
    private TreeNode find(TreeNode node, int x) {
        if (node == null || node.val == x) return node;
        TreeNode l = find(node.left, x);
        return l != null ? l : find(node.right, x);
    }
    private int size(TreeNode node) {
        return node == null ? 0 : 1 + size(node.left) + size(node.right);
    }
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        TreeNode xn = find(root, x);
        int l = size(xn.left), r = size(xn.right);
        int rest = n - l - r - 1;
        return Math.max(l, Math.max(r, rest)) > n / 2;
    }
}

