        self.l = self.r = 0
        def dfs(node):
            if not node:
                return 0
            ls, rs = dfs(node.left), dfs(node.right)
            if node.val == x:
                self.l, self.r = ls, rs
            return 1 + ls + rs
        dfs(root)
        rest = n - self.l - self.r - 1
        return max(self.l, self.r, rest) > n // 2

